import type { LootTableDef, StageDef, StageRole, ZoneDef } from "@emberbound/shared-types";
import { STAGE_BUDGETS } from "./budgets.generated";

/**
 * Adventure zones (C1). Ten stages each: 1–4 normal, 5 Elite, 6–9 normal, 10 Zone Boss.
 *
 * Stage HP and damage budgets are plain integers generated by
 * `bun tools/sim/tune-budgets.ts`. That tool calibrates them against the expected build
 * at each zone's first clear (tools/sim/expected-builds.ts, docs/design/C1_ADVENTURE.md).
 * Re-run it after changing classes, items, enemies or stage compositions.
 */

function stages(zoneId: string, defs: [StageRole, number, string[]][]): StageDef[] {
  const budget = STAGE_BUDGETS[zoneId];
  return defs.map(([role, level, enemies], index) => ({
    index,
    role,
    level,
    // Placeholders only until the calibration tool has written this zone.
    hpBudget: budget?.hp[index] ?? 100,
    dpsBudget100: budget?.dps[index] ?? 100,
    enemies,
  }));
}

